tasks.description:
f'
Screen risk for order {rec_id}:
- Customer ID: {cust_id}
- Customer Tier: {tier}
- Order Total USD: {total}
- Billing Country: {country}

Rule: If customer_tier is "new" and order_total_usd >= 5000, risk_band="high" and review_flag=true. Else if order_total_usd >= 2000, risk_band="medium" and review_flag=false. Otherwise risk_band="low" and review_flag=false.
Return ONLY valid JSON:
{{
  "record_id": "{rec_id}",
  "risk_band": "low|medium|high",
  "review_flag": true or false,
  "screen_note": "Brief risk summary"
}}
'

f'
{VERBOSE_POLICY_MANUAL}

UPSTREAM PAYLOADS FOR EXECUTION RUN {run_id} / RECORD {record_id}:
- Inventory: {inventory_output}
- Fraud Screen: {fraud_output}
- Carrier Routing: {routing_output}
- Tax Classification: {tax_output}
- Invoice Tagging: {invoice_output}

Return ONLY strictly valid JSON matching this exact structure:
{{
  "run_id": "{run_id}",
  "record_id": "{record_id}",
  "final_decision": "APPROVE" | "HOLD_FOR_REVIEW" | "REJECT",
  "carrier_name": "{routing_output.get('carrier_name', 'UPS')}",
  "service_level": "{routing_output.get('service_level', 'Standard')}",
  "tax_jurisdiction": "{tax_output.get('tax_jurisdiction', 'US-TAX')}",
  "tax_amount_usd": {tax_output.get('tax_amount_usd', 0.0)},
  "invoice_tag": "{invoice_output.get('invoice_tag', 'INV-000')}",
  "summary": "Concise 1-2 sentence dispatch summary grounded in upstream outputs.",
  "human_review_required": true or false
}}
'

f'
Check stock availability for order {rec_id}:
- Warehouse Region: {wh_region}
- SKU Items: {json.dumps(skus)}

Rule: If every item has stock_available >= qty (and stock_available > 0), in_stock is true and backorder_skus is []. Otherwise in_stock is false and list affected sku codes in backorder_skus.
Return ONLY valid JSON:
{{
  "record_id": "{rec_id}",
  "in_stock": true or false,
  "warehouse_code": "WH-{wh_region}",
  "backorder_skus": [],
  "inventory_note": "Brief factual stock summary"
}}
'
